mapper.select:
SELECT ROOM_ID, ROOM_NM, LOCATION, CAPACITY, USE_YN, REMARK, REGIST_DT, UPDT_DT
FROM MEETING_ROOM
WHERE ROOM_ID = #{roomId}

SELECT R.RESERVE_ID, R.ROOM_ID, M.ROOM_NM, M.LOCATION, R.USER_ID, U.USER_NM, R.RESERVE_DE, R.START_TIME, R.END_TIME, R.TITLE, R.PURPOSE, R.REGIST_DT FROM MEETING_RESERVATION R JOIN MEETING_ROOM M ON M.ROOM_ID = R.ROOM_ID LEFT JOIN APP_USER U ON U.USER_ID = R.USER_ID
AND R.RESERVE_DE = #{reserveDe}
AND R.ROOM_ID = #{roomId}
AND (R.TITLE LIKE '%' || #{searchKeyword} || '%' OR R.USER_ID LIKE '%' || #{searchKeyword} || '%' OR U.USER_NM LIKE '%' || #{searchKeyword} || '%')
ORDER BY R.RESERVE_DE DESC, R.START_TIME, R.ROOM_ID

SELECT RESERVE_ID, ROOM_ID, USER_ID, RESERVE_DE, START_TIME, END_TIME, TITLE, PURPOSE
FROM MEETING_RESERVATION
WHERE RESERVE_ID = #{reserveId}

SELECT COUNT(*)
FROM MEETING_RESERVATION
WHERE ROOM_ID = #{roomId}
	AND RESERVE_DE = #{reserveDe}
	AND START_TIME < #{endTime}
	AND END_TIME > #{startTime}

mapper.insert:
INSERT INTO MEETING_RESERVATION (
	RESERVE_ID, ROOM_ID, USER_ID, RESERVE_DE, START_TIME, END_TIME, TITLE, PURPOSE, REGIST_DT
) VALUES (
	#{reserveId}, #{roomId}, #{userId}, #{reserveDe}, #{startTime}, #{endTime}, #{title}, #{purpose}, CURRENT_TIMESTAMP
)

mapper.delete:
DELETE FROM MEETING_RESERVATION
WHERE RESERVE_ID = #{reserveId}

	AND USER_ID = #{userId}
